function wikiCueCards(){if(typeof SUMMON_CUE_SPECS==='undefined')return'';return Object.keys(SUMMON_CUE_SPECS).map((key)=>{const spec=SUMMON_CUE_SPECS[key];const tier=typeof TYPE_EGG_RARITIES!=='undefined'&&TYPE_EGG_RARITIES[key]?TYPE_EGG_RARITIES[key]:null;const layers=spec.layers.map(([type,at,raw])=>{const opts=raw||{};const bits=[`starts ${Number(at).toFixed(2)}s`];if(Number.isFinite(opts.dur))bits.push(`${Number(opts.dur).toFixed(2)}s long`);if(Number.isFinite(opts.freq))bits.push(`${opts.freq} Hz`);if(Number.isFinite(opts.count))bits.push(`${opts.count} pings`);if(Number.isFinite(opts.vol))bits.push(`vol ${Math.round(opts.vol * 1000) / 10}%`);return `<li><b>${type}</b> \u00b7 ${bits.join(' \u00b7 ')}</li>`;}).join('');return `<div class="wiki-cue-card" data-cue-tier="${key}" style="--rarity:${tier && tier.color ? tier.color : '#c9cdd2'}">
      <div class="wc-head">
        <span class="wc-icon">${tier && tier.icon ? tier.icon : '\u{1F3B5}'}</span>
        <span class="wc-copy"><b>${esc(tier && tier.name ? tier.name : key)}</b><small>${spec.length}s \u00b7 ${spec.layers.length} layers \u00b7 ${esc(spec.theme)}</small></span>
        <button class="wc-play" type="button" data-wiki-cue="${key}">\u25b6 Play</button>
      </div>
      <details><summary>Layers \u00b7 ${spec.layers.length}</summary><ul class="wiki-list">${layers}</ul></details>
    </div>`;}).join('');}
function wikiHabitats(key){return SCENE_KEYS.filter((sceneKey)=>!SCENES[sceneKey].custom&&(SCENES[sceneKey].species||[]).includes(key));}
