          return `<div class="wiki-show-block"><h4>${info.icon} ${esc(info.label)} · ${info.gene[1]} ${esc(info.gene[0])}</h4><p>${esc(info.note)}</p><div class="wiki-hybrid-list">${NETFLIX_BY_SHOW[show].map(link).join('')}</div></div>`;
